import{U as e,W as t,nt as n,t as r}from"./chunks/framework.CWvfYWS8.js";import"./chunks/assets.Bz7j3IzC.js";var i=JSON.parse(`{"title":"PSI 压力指标","description":"","frontmatter":{},"headers":[],"relativePath":"zh/ch003.md","filePath":"zh/ch003.md"}`),a={name:`zh/ch003.md`};function o(r,i,a,o,s,c){return n(),e(`div`,null,[...i[0]||=[t(`<h1 id="psi-压力指标" tabindex="-1">PSI 压力指标 <a class="header-anchor" href="#psi-压力指标" aria-label="Permalink to “PSI 压力指标”">​</a></h1><p><a href="https://facebookmicrosites.github.io/psi/" target="_blank" rel="noreferrer">压力停滞信息(PSI)</a> 指标首次提供了一种规范化方式，可在资源压力形成过程中观察其增长，并为内存、CPU 和 IO 三类主要资源提供了新的压力指标。</p><p>这些压力指标与 cgroup2 以及本指南介绍的其他内核和用户空间工具结合使用，可提供必要信息，让你在资源短缺形成过程中检测到它，并智能响应——暂停或终止非必要进程、在系统中重新分配内存，或进行<a href="./ch012.html#pressure-based-load-shedding">减载</a>。</p><p>这些压力指标与 cgroup2 以及本指南介绍的其他内核和用户空间工具结合使用，可提供必要信息，让你在资源短缺形成过程中检测到它，并智能响应——暂停或终止非必要进程、在系统中重新分配内存，或进行减载。</p><h2 id="cgroup2-接口" tabindex="-1">cgroup2 接口 <a class="header-anchor" href="#cgroup2-接口" aria-label="Permalink to “cgroup2 接口”">​</a></h2><p>在已挂载 cgroup2 文件系统的系统中，会针对分组到 cgroup 中的任务跟踪压力停滞信息。<code>cgroupfs</code> 挂载点中每个 cgroup 控制器对应的子目录都包含 <code>cpu.pressure</code>、<code>memory.pressure</code> 和 <code>io.pressure</code> 文件。</p><p>通过运行以下命令查询某个 cgroup 的 PSI。此示例查询名为 cg1 的 cgroup 的 <code>cpu.pressure</code>：</p><div class="language-bash" dir="ltr"><button title="复制代码" data-copied="已复制" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cat</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /sys/fs/cgroup/cg1/cpu.pressure</span></span></code></pre></div><p>CPU 的输出格式为：</p><div class="language-plaintext" dir="ltr"><button title="复制代码" data-copied="已复制" class="copy"></button><span class="lang">plaintext</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>some avg10=0.00 avg60=0.00 avg300=0.00 total=0</span></span></code></pre></div><p>内存和 IO 为：</p><div class="language-plaintext" dir="ltr"><button title="复制代码" data-copied="已复制" class="copy"></button><span class="lang">plaintext</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>some avg10=0.00 avg60=0.00 avg300=0.00 total=0</span></span>
<span class="line"><span>full avg10=0.00 avg60=0.00 avg300=0.00 total=0</span></span></code></pre></div><p>内存和 IO 显示两个指标：<code>some</code> 和 <code>full</code>。CPU 控制器仅显示 <code>some</code> 指标。<code>some</code> 和 <code>full</code> 的值分别以最近 10 秒、1 分钟和 5 分钟的滑动平均值显示。<code>total</code> 统计值是累计微秒数。</p><p>PSI 将压力表示为实际时间（walltime）的百分比，在该时间内有部分或全部进程因资源而阻塞：</p><ul><li><code>some</code> 是有部分（一个或多个）任务因资源不足（例如内存不足）而被延迟的实际时间百分比。</li><li><code>full</code> 是所有任务都因资源不足而被延迟的实际时间百分比，即完全无产出的时间量。</li></ul><p>有关这些指标的更多细节，请参阅 <a href="https://facebookmicrosites.github.io/psi/docs/overview.html#pressure-metric-definitions" target="_blank" rel="noreferrer">PSI 文档</a>。</p><h2 id="fbtax2-项目中的内存压力" tabindex="-1">fbtax2 项目中的内存压力 <a class="header-anchor" href="#fbtax2-项目中的内存压力" aria-label="Permalink to “fbtax2 项目中的内存压力”">​</a></h2><div class="danger custom-block"><p>借助 PSI 内存压力指标，fbtax2 团队终于有了一种工具，可以判断给定工作负载是否有足够内存，并提供对系统内存使用情况的总体洞察；这比他们此前不得不依赖的试错过程要好。</p><p>正如<a href="./ch002.html#the-fbtax2-cgroup-hierarchy">前文</a>所述，设计 <strong>fbtax2</strong> cgroup 层级的一个关键目标是保护 <code>workload.slice</code>，使其免受 <code>system.slice</code> 中广泛分布的系统二进制程序的资源冲突影响。</p><p><code>system.slice</code> 中的进程通常不像 <code>workload.slice</code> 中的进程那样对延迟敏感，并且通常能够挺过由内存不足引起的减速而不会造成严重后果。因此，<code>workload.slice</code> 获得资源优先级，代价是 <code>system.slice</code> 出现减速，从而帮助确保主工作负载的稳定性。</p><p>此图展示了 PSI 内存压力指标如何让团队清楚地看到其努力的结果：<code>system.slice</code> 的 <code>memory.pressure.full</code>（绿线）最高飙升至 50%（右侧 X 轴），而 <code>workload.slice</code> 的压力（橙线）保持在 10% 以下，表明其内存优先级和保护程度提高。与此同时，系统整体性能（蓝线）在 500 到 600 rps 之间保持相对稳定（左侧 X 轴）。</p><p><img src="/p002/ch00/004.png" alt="" width="1000" height="600"></p><p>我们将在本案例研究的<a href="./ch011.html#the-fbtax2-memory-controller-configuration">下一节</a>中介绍 <strong>fbtax2</strong> 为获得这些结果所使用的具体内存控制器配置。</p></div>`,18)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};